package builderadmin

const buildDetailHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Build details</title><style>{{ browserTokens .Theme }}</style><style>:root{--bg:var(--markata-background);--panel:var(--markata-panel);--text:var(--markata-text-primary);--muted:var(--markata-text-secondary);--link:var(--markata-link);--line:var(--markata-border);--code-bg:var(--markata-code-background);--code-text:var(--markata-code-text)}body{max-width:1000px;margin:auto;padding:32px;background:var(--bg);color:var(--text);font:15px system-ui}a{color:var(--link)}button{font:inherit;padding:.55rem .8rem;border:1px solid var(--line);border-radius:.45rem;background:var(--panel);color:var(--text);cursor:pointer}button:hover{border-color:var(--link)}pre{white-space:pre-wrap;background:var(--code-bg);color:var(--code-text);padding:16px}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}dt{color:var(--muted);font-size:.8rem}dd{margin:4px 0}section{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}.report-actions{display:flex;flex-wrap:wrap;gap:.6rem;align-items:center}.report-status{color:var(--muted);font-size:.9rem}@media(max-width:700px){body{padding:20px}dl{grid-template-columns:1fr 1fr}}</style></head><body><a href="/#jobs">← Jobs</a><h1>{{ if .RollbackRelease }}Release promotion{{ else }}Build{{ end }}</h1><p><span id="report-status-value">{{ .Status }}</span> · finished {{ since .FinishedAt }}</p><dl><div><dt>Trigger</dt><dd id="report-trigger">{{ .TriggerType }}</dd></div><div><dt>Queue wait</dt><dd id="report-queue-wait">{{ msToSeconds .QueueWaitMS }}</dd></div><div><dt>Prepare time</dt><dd id="report-prepare-time">{{ msToSeconds .PrepareMS }}</dd></div><div><dt>Build time</dt><dd id="report-build-time">{{ msToSeconds .BuildMS }}</dd></div><div><dt>Promote time</dt><dd id="report-promote-time">{{ msToSeconds .PromoteMS }}</dd></div><div><dt>Prune time</dt><dd id="report-prune-time">{{ msToSeconds .PruneMS }}</dd></div><div><dt>Total time</dt><dd id="report-total-time">{{ msToSeconds .TotalMS }}</dd></div><div><dt>Release</dt><dd>{{ if .BecameLive }}Live{{ else }}Not promoted{{ end }}</dd></div><div><dt>Build ID</dt><dd id="report-build-id">{{ .ID }}</dd></div>{{ if .BuilderVersion }}<div><dt>Builder version</dt><dd id="report-builder-version">{{ .BuilderVersion }}</dd></div>{{ end }}{{ if .BuilderCommit }}<div><dt>Builder revision</dt><dd><code id="report-builder-revision">{{ .BuilderCommit }}</code></dd></div>{{ end }}{{ if .SourceCommit }}<div><dt>Site source revision</dt><dd><code id="report-source-revision">{{ .SourceCommit }}</code></dd></div>{{ end }}</dl>{{ if .ReleaseID }}<section><a href="{{ .PreviewURL }}">Open protected preview</a></section>{{ end }}{{ if .TriggerDetail }}<section><h2>Reason</h2><p id="report-reason">{{ .TriggerDetail }}</p></section>{{ end }}{{ if .ChangedPaths }}<section><h2>Changed paths</h2><pre id="report-changed-paths">{{ range .ChangedPaths }}{{ . }}
{{ end }}</pre></section>{{ end }}{{ if .PerfSummary }}<section><h2>Performance summary</h2><pre id="report-performance-summary">{{ range .PerfSummary }}{{ . }}
{{ end }}</pre></section>{{ end }}{{ if .LogDiagnostics }}<section><h2>Build diagnostics</h2><pre id="report-diagnostics">{{ range .LogDiagnostics }}[{{ .Severity }}] {{ .Code }}: {{ .Message }}{{ if .File }} ({{ .File }}{{ if .Line }}:{{ .Line }}{{ end }}){{ end }}{{ if .SuggestedFix }}
  Suggested fix: {{ .SuggestedFix }}{{ end }}
{{ end }}</pre></section>{{ end }}{{ if .Error }}<section><h2>Build error</h2><pre id="report-error">{{ .Error }}</pre></section>{{ end }}<section><h2>Diagnostic handoff</h2><p>Generate a portable Markdown report from the sanitized build data shown on this page. Raw logs, environment values, credentials, and absolute release paths are not included.</p><div class="report-actions"><button type="button" id="copy-diagnostic-report">Copy diagnostic report</button><button type="button" id="download-diagnostic-report">Download report</button><span class="report-status" id="diagnostic-report-status" role="status" aria-live="polite"></span></div></section>{{ if .LogPath }}<section><a href="/logs/{{ .LogPath }}">Open raw log</a></section>{{ end }}<script>(function(){function text(id){var el=document.getElementById(id);return el?el.textContent.trim():""}function section(title,id){var value=text(id);return value?"\n## "+title+"\n\n"+value+"\n":""}function report(){var out="# Markata-Go Builder Diagnostic Report\n\n";out+="- Build ID: "+text("report-build-id")+"\n";if(text("report-builder-revision"))out+="- Builder revision: "+text("report-builder-revision")+"\n";if(text("report-source-revision"))out+="- Site source revision: "+text("report-source-revision")+"\n";out+="- Status: "+text("report-status-value")+"\n";out+="- Trigger: "+text("report-trigger")+"\n";out+="- Queue wait: "+text("report-queue-wait")+"\n";out+="- Prepare: "+text("report-prepare-time")+"\n";out+="- Build: "+text("report-build-time")+"\n";out+="- Promote: "+text("report-promote-time")+"\n";out+="- Prune: "+text("report-prune-time")+"\n";out+="- Total: "+text("report-total-time")+"\n";out+=section("Reason","report-reason");out+=section("Changed paths","report-changed-paths");out+=section("Performance summary","report-performance-summary");out+=section("Build diagnostics","report-diagnostics");out+=section("Build error","report-error");return out}function status(message){document.getElementById("diagnostic-report-status").textContent=message}function fallbackCopy(value){var area=document.createElement("textarea");area.value=value;area.setAttribute("readonly","");area.style.position="fixed";area.style.opacity="0";document.body.appendChild(area);area.select();var ok=document.execCommand("copy");area.remove();return ok}document.getElementById("copy-diagnostic-report").addEventListener("click",function(){var value=report();if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(value).then(function(){status("Copied diagnostic report")},function(){status(fallbackCopy(value)?"Copied diagnostic report":"Copy failed")})}else{status(fallbackCopy(value)?"Copied diagnostic report":"Copy failed")}});document.getElementById("download-diagnostic-report").addEventListener("click",function(){var value=report();var blob=new Blob([value],{type:"text/markdown;charset=utf-8"});var url=URL.createObjectURL(blob);var link=document.createElement("a");link.href=url;link.download="markata-builder-"+(text("report-build-id")||"build")+"-diagnostic.md";document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);status("Downloaded diagnostic report")})})();</script></body></html>`
